INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Projektwerkzeuge im Projektmanagement essenziell?', 2, '[{"text": "Ja", "correct": true, "because": "Fördern Struktur und Effizienz"}, {"text": "Nein", "correct": false, "because": "Erleichtern Abläufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Projektwerkzeuge?', 3, '[{"text": "Projektsteuerung unterstützen", "correct": true, "because": "Verbessern Übersicht"}, {"text": "Team direkt motivieren", "correct": false, "because": "Nebenaspekt"}, {"text": "Kosten automatisch senken", "correct": false, "because": "Indirekter Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektwerkzeuge helfen bei der Planung. b) Sie werden nur in der Durchführung genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Phasen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Projektwerkzeugen gibt es?', 4, '[{"text": "Planungstools", "correct": true, "because": "Wie Gantt-Diagramme"}, {"text": "Unstrukturierte Listen", "correct": false, "because": "Keine Werkzeuge"}, {"text": "Kommunikationstools", "correct": true, "because": "Wie Chat-Plattformen"}, {"text": "Controlling-Tools", "correct": true, "because": "Wie Earned Value"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Werkzeuge erfolgreich sein?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell möglich"}, {"text": "Nein", "correct": false, "because": "Werkzeuge optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Zeitplanung?', 3, '[{"text": "Microsoft Project", "correct": true, "because": "Erstellt Zeitpläne"}, {"text": "Keine Software", "correct": false, "because": "Fehlt Struktur"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Projektwerkzeuge nur für große Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Projektwerkzeuge?', 3, '[{"text": "Effizienz und Übersicht fördern", "correct": true, "because": "Unterstützen Steuerung"}, {"text": "Neue Ziele definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Team neu einteilen", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Werkzeuge verbessern Kommunikation. b) Sie sind immer kostenfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft kostenpflichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
