('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Projektwerkzeug?', 3, '[{"text": "Trello für Aufgabenverwaltung", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas schreiben", "correct": false, "because": "Zu vage"}, {"text": "Team soll planen", "correct": false, "because": "Kein Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Projektwerkzeuge nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Team nutzt sie auch"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen haben Projektwerkzeuge?', 4, '[{"text": "Zeitmanagement", "correct": true, "because": "Steuert Termine"}, {"text": "Unklare Berichte", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Aufgabenverfolgung", "correct": true, "because": "Überwacht Fortschritt"}, {"text": "Kommunikation", "correct": true, "because": "Fördert Austausch"}]'),
